"use client";

import * as React from "react";
import styles from "../styles/scroll-velocity-progress.module.css";

export interface ScrollVelocityProgressProps {
  /** Scroll completion percentage (0 to 100) */
  progress?: number;
  /** Velocity multiplier (0 to 4) */
  velocity?: number;
  /** Orientation mode */
  orientation?: "horizontal" | "vertical";
  /** Bar accent color */
  accentColor?: string;
  /** Optional className */
  className?: string;
}

export function ScrollVelocityProgress({
  progress = 64,
  velocity = 1.8,
  orientation = "horizontal",
  accentColor = "#38bdf8",
  className = "",
}: ScrollVelocityProgressProps) {
  const clampedProgress = Math.min(100, Math.max(0, progress));
  const thickness = Math.min(12, 4 + velocity * 1.6);

  return (
    <div className={`${styles.card} ${className}`.trim()}>
      <div className={styles.metaRow}>
        <span className={styles.label}>SCROLL VELOCITY TELEMETRY</span>
        <span className={styles.readout}>
          {clampedProgress}% • {velocity.toFixed(1)}x vel
        </span>
      </div>

      <div
        role="progressbar"
        aria-label="Page scroll progress"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(clampedProgress)}
        className={orientation === "vertical" ? styles.trackVertical : styles.trackHorizontal}
        style={
          orientation === "vertical"
            ? { width: `${thickness}px` }
            : { height: `${thickness}px` }
        }
      >
        <div
          className={styles.fill}
          style={
            orientation === "vertical"
              ? {
                  height: `${clampedProgress}%`,
                  width: "100%",
                  backgroundColor: accentColor,
                  boxShadow: `0 0 ${Math.round(velocity * 6)}px ${accentColor}`,
                }
              : {
                  width: `${clampedProgress}%`,
                  height: "100%",
                  backgroundColor: accentColor,
                  boxShadow: `0 0 ${Math.round(velocity * 6)}px ${accentColor}`,
                }
          }
        />
      </div>
    </div>
  );
}

.card {
  width: 100%;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-surface-raised, #25252f);
  background-color: var(--mf-surface, #101015);
  padding: 1.15rem 1.35rem;
  color: var(--mf-fg, #f4f4f6);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.metaRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.72rem;
}

.label {
  color: var(--mf-muted, #a1a1aa);
}

.readout {
  color: var(--mf-fg, #f4f4f6);
}

.trackHorizontal {
  width: 100%;
  border-radius: 999px;
  background-color: var(--mf-surface-raised, #1e1e28);
  overflow: hidden;
  transition: height 160ms ease;
}

.trackVertical {
  height: 7.5rem;
  border-radius: 999px;
  background-color: var(--mf-surface-raised, #1e1e28);
  overflow: hidden;
  align-self: center;
  transition: width 160ms ease;
}

.fill {
  border-radius: 999px;
  transition: width 160ms ease, height 160ms ease, box-shadow 160ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .trackHorizontal,
  .trackVertical,
  .fill {
    transition: none;
  }
}

